"""Read-only summary of mailtodo letters."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re


NAME_STAMP = re.compile(r"^([0-9]{8}T[0-9]{4})[-_]")
RESOLVING = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}
MINUTE = timedelta(minutes=1)


def frontmatter(path):
    try:
        lines = path.read_text(encoding="utf-8").split("\n")
    except (OSError, UnicodeError):
        return None
    if lines[0] != "---":
        return None
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    return fields


def parse_letter(path, now):
    fields = frontmatter(path)
    if fields is None:
        return None, "no_frontmatter"
    if any(not fields.get(key) for key in ("id", "from", "to", "status")):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields.get("at", ""))
    except ValueError:
        return None, "no_field"
    if at.tzinfo is None:
        at = at.replace(tzinfo=now.tzinfo)
    match = NAME_STAMP.match(path.name)
    try:
        if match is None:
            raise ValueError("missing filename timestamp")
        datetime.strptime(match.group(1), "%Y%m%dT%H%M")
    except ValueError:
        return None, "bad_name"
    return (fields, at), None


def candidates(root):
    boxes = {}
    paths = []
    for box in sorted(root.iterdir(), key=lambda item: item.name):
        if box.name.startswith(".") or box.is_symlink() or not box.is_dir():
            continue
        inbox = box / "inbox"
        if inbox.is_symlink() or not inbox.is_dir():
            continue
        boxes[box.name] = {"inbox": {}, "done": 0}
        for where, directory in (("inbox", inbox), ("done", inbox / "done")):
            if directory.is_symlink() or not directory.is_dir():
                continue
            for path in directory.iterdir():
                if (not path.name.startswith(".") and path.suffix == ".md"
                        and not path.is_symlink() and path.is_file()):
                    paths.append((path.relative_to(root).as_posix(), box.name, where, path))
    return boxes, sorted(paths, key=lambda item: item[0])


def summarize(root, now):
    boxes, paths = candidates(root)
    bad = []
    letters = []
    seen = set()
    for relative, box, where, path in paths:
        letter, why = parse_letter(path, now)
        if why is None:
            fields, at = letter
            if fields["id"] in seen:
                why = "dup_id"
            else:
                seen.add(fields["id"])
                letters.append((fields, at, box, where))
                if where == "inbox":
                    counts = boxes[box]["inbox"]
                    status = fields["status"]
                    counts[status] = counts.get(status, 0) + 1
                else:
                    boxes[box]["done"] += 1
        if why is not None:
            bad.append({"file": relative, "why": why})
    resolved = {fields.get("re") for fields, _, _, _ in letters
                if fields["status"] in RESOLVING and fields.get("re")}
    opened = [{"id": fields["id"], "from": fields["from"], "to": fields["to"],
               "where": where, "age_min": (now - at) // MINUTE}
              for fields, at, _, where in letters
              if fields["status"] == "REQUEST" and fields["id"] not in resolved]
    opened.sort(key=lambda item: (item["to"], item["id"]))
    bad.sort(key=lambda item: (item["file"], item["why"]))
    return {"v": 1, "open": opened, "boxes": boxes, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Summarize mailtodo without writing to the node")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=True,
                     separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
